// SwiftRun web - serves the single-file app for swiftrun.online and www.
// NOTE: this is the source for the deployed swiftrun-web worker (plain,
// dependency-free). A hono-based alternative lives in worker/src/index.js
// from a parallel run; the LIVE deployment is this file.
const HTML_B64 = '';
let HTML = null;
function getHtml() {
  if (!HTML) {
    const bin = atob(HTML_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    HTML = new TextDecoder().decode(bytes);
  }
  return HTML;
}
export default {
  fetch(req) {
    return new Response(getHtml(), {
      headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300' },
    });
  },
};
